42	func TestAmountLimitSetValidation(t *testing.T) {
43		e := setupAmt(t)
44	
45		if _, err := e.SetPositionAmountLimit(-1); err == nil {
46			t.Fatal("负上限必须报错")
47		}
48		if e.PositionAmountStatus().Enabled {
49			t.Fatal("负上限不得启用限额")
50		}
51	
52		// 首次设置为 0：允许且立即生效；同值重复设置无操作、无记录。
53		before := len(e.Records())
54		if _, err := e.SetPositionAmountLimit(0); err != nil {
55			t.Fatal(err)
56		}
57		if _, err := e.SetPositionAmountLimit(0); err != nil {
58			t.Fatal(err)
59		}
60		if len(e.Records()) != before {
61			t.Fatal("同值重复设置不得产生记录")
62		}
63		if st := e.PositionAmountStatus(); !st.Enabled || st.Limit != 0 {
64			t.Fatalf("零上限应已启用: %+v", st)
65		}
66	}
