188	func TestAmountHoldingOnlyOverLimitCancelsAllButNoSell(t *testing.T) {
189		e := setupAmt(t)
190		id := mustBuy(t, e, "A", 10, 10)
191		if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
192			t.Fatal(err)
193		}
194		b1 := mustBuy(t, e, "A", 1, 10)
195		b2 := mustBuy(t, e, "B", 1, 20)
196	
197		// 上限 99：持仓市值 100 仅持仓就超限 → 撤光全部买单，不自动卖出。
198		canceled, err := e.SetPositionAmountLimit(99)
199		if err != nil {
200			t.Fatal(err)
201		}
202		if len(canceled) != 2 || canceled[0] != b2 || canceled[1] != b1 {
203			t.Fatalf("仅持仓超限时应撤光买单（降序）: %v", canceled)
204		}
205		if e.Position("A") != 10 {
206			t.Fatal("不得自动卖出持仓")
207		}
208		if st := e.PositionAmountStatus(); st.Holding != 100 || st.BuyReserved != 0 || st.Total != 100 {
209			t.Fatalf("撤光买单后只剩持仓金额: %+v", st)
210		}
211		if _, err := e.Buy("A", 1, 1); err == nil {
212			t.Fatal("仍超限期间新买单必须拒绝")
213		}
214	
215		// 正常卖单及其成交仍允许；卖出后持仓金额下降、额度恢复便可再次买入。
216		sid := mustSell(t, e, "A", 2, 1)
217		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 10, Qty: 2}); err != nil {
218			t.Fatal(err)
219		}
220		if st := e.PositionAmountStatus(); st.Holding != 80 || st.Total != 80 {
221			t.Fatalf("卖出成交应减少持仓金额: %+v", st)
222		}
223		mustBuy(t, e, "A", 1, 9) // 80 + 1×max(9,报价10)=10 → 90 ≤ 99，恢复买入
224	}
