348	func TestAmountGapAppliesOneByOneAndIntermediateCancelsStick(t *testing.T) {
349		e := setupAmt(t)
350		if _, err := e.SetPositionAmountLimit(100); err != nil {
351			t.Fatal(err)
352		}
353		b1 := mustBuy(t, e, "A", 5, 10) // 占用 50
354		b2 := mustBuy(t, e, "A", 5, 10) // 占用 50，合计 100
355	
356		// seq3 报价 20 跨号等待：不参与计算，合计仍 100。
357		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 20}, 0)
358		if st := e.PositionAmountStatus(); st.BuyReserved != 100 || st.Total != 100 {
359			t.Fatalf("等待补齐的报价不得参与计算: %+v", st)
360		}
361	
362		// 补齐 seq2@12：两条买单各变 60，第一条生效即超限，撤 b2 后仍 60 ≤ 100；
363		// 接着 seq3@20：b1 变 100 恰好等于上限，保留。
364		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 12}, 2)
365		if o, _ := e.Order(b2); o.Status != StatusCanceled {
366			t.Fatalf("seq2@12 应撤销编号最大的 b2: %+v", o)
367		}
368		if o, _ := e.Order(b1); o.Status != StatusPending {
369			t.Fatalf("seq3@20 下 b1 占用恰 100，应保留: %+v", o)
370		}
371	
372		// 中间报价造成的撤单即使最后价格回落也保留。
373		e2 := setupAmt(t)
374		if _, err := e2.SetPositionAmountLimit(100); err != nil {
375			t.Fatal(err)
376		}
377		c1 := mustBuy(t, e2, "A", 10, 10)
378		mustQuote(t, e2, "A", Quote{Seq: 3, Moment: 3, Price: 5}, 0)
379		mustQuote(t, e2, "A", Quote{Seq: 2, Moment: 2, Price: 20}, 2)
380		if o, _ := e2.Order(c1); o.Status != StatusCanceled {
381			t.Fatal("链中 seq2@20 造成的撤单必须保留")
382		}
383		mustQuote(t, e2, "A", Quote{Seq: 4, Moment: 4, Price: 10}, 1)
384		if o, _ := e2.Order(c1); o.Status != StatusCanceled {
385			t.Fatal("最后价格回落不得恢复已撤订单")
386		}
387	}
