389	func TestAmountCoexistsWithLossProtection(t *testing.T) {
390		// 现金 1000，A 持仓 10@10（成本 100）。
391		e := setupHolding(t, 10)
392		// 金额上限 200：买单 id=2，10 股限价 10，占用 100。
393		if _, err := e.SetPositionAmountLimit(200); err != nil {
394			t.Fatal(err)
395		}
396		bid := mustBuy(t, e, "A", 10, 10)
397	
398		// 开启亏损保护；报价跌到 1：亏损 90 达限（上限 90），亏损保护先撤光买单。
399		if err := e.StartTradingDay(1, 90); err != nil {
400			t.Fatal(err)
401		}
402		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 1}, 1)
403		if !e.RiskStatus().Restricted {
404			t.Fatal("亏损保护应触发")
405		}
406		if o, _ := e.Order(bid); o.Status != StatusCanceled {
407			t.Fatalf("亏损保护应撤销买单: %+v", o)
408		}
409		// 撤单原因必须保留亏损保护的原因，不得被金额上限改写。
410		var cancelRec Record
411		for _, r := range e.Records() {
412			if r.Kind == RecordCanceled && r.OrderID == bid {
413				cancelRec = r
414			}
415		}
416		if cancelRec.Reason == "" || !strings.Contains(cancelRec.Reason, "亏损") {
