10	// 重点覆盖同一账户同时持有其他合约买单与目标合约卖单占用时，下调一个合约的
11	// 限额只处理这个合约的有效买单剩余量，全部结论以公开的订单、资金、持仓与
12	// 事件记录查询为准（未启用日内亏损保护与账户总持仓金额上限）。
13	//
14	// 固定场景（整数金额口径）：
15	//   - 初始现金 1000；A、B 最大持仓量均为 20。
16	//   - 已生效报价：A 序号1、时刻10、价格10；B 序号1、时刻20、价格5。
17	//   - 接受 A 买单 10@10（订单1），其中 3 份按价格 9 成交：现金 973、A 持仓 3。
18	//   - 接受 A 买单 2@12（订单2），再接受 B 买单 4@5（订单3）。
19	//   - 接受 A 卖单 2@8（订单4，占用 A 可卖 2 份，尚未成交）。
20	//   - 前置口径：A 持仓 3、可卖 1；现金余额 973；买单共占用现金 114
21	//     （订单1 剩余 7 份占 70，订单2 占 24，订单3 占 20），可用 859。
22	//
23	// 第一次下调 A 限额到 10：持仓 3 + A 买单剩余 9 = 12 超限，只撤销最后接受的
24	// A 买单（订单2），返回的撤销编号只含这一单；订单1 保留部分成交状态（已成交 3、
25	// 剩余 7），持仓与剩余量合计恰好达到新限额即停止。B 买单（订单3）虽然接受得更晚，
26	// 仍保持有效；A 卖单数量与可卖占用不变。撤单释放 24 现金：余额仍为 973（已成交
27	// 部分的实际金额不退回），占用 90，可用 883。
28	//
29	// 第二次下调 A 限额到 2：持仓 3 本身已超过新限额（待成交卖单不能提前抵减持仓），
30	// 撤销订单1 的全部剩余 7 份，保留其已成交 3 份，不自动卖出持仓。此后占用现金只剩
31	// B 买单的 20，A 持仓 3、可卖 1，卖单继续有效。两次撤销记录按实际撤销顺序保存，
32	// 分别说明限额变化原因、携带各自当时的 A 报价与新限额快照，并区分已成交数量与被
33	// 取消的剩余数量；第二次下调不改写第一次的记录，既有成交记录也保持原值。
34	
35	// lowerMaxSetup 构造下调限额前的共用前置状态，返回引擎与四个订单编号
36	// （bidA1：A 部分成交买单；bidA2：A 待成交买单；bidB：B 待成交买单；sellA：A 有效卖单）。
37	func lowerMaxSetup(t *testing.T) (e *Engine, bidA1, bidA2, bidB, sellA int64) {
38		t.Helper()
39		e, _ = NewEngine(1000)
40		mustSetMax(t, e, "A", 20)
41		mustSetMax(t, e, "B", 20)
42		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 10, Price: 10}, 1)
43		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 20, Price: 5}, 1)
44	
45		bidA1 = mustBuy(t, e, "A", 10, 10)
46		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bidA1, Symbol: "A", Side: Buy, Price: 9, Qty: 3}); err != nil {
47			t.Fatal(err)
48		}
49		bidA2 = mustBuy(t, e, "A", 2, 12)
50		bidB = mustBuy(t, e, "B", 4, 5)
51		sellA = mustSell(t, e, "A", 2, 8)
52	
53		// 题目给定的前置资金与持仓口径，逐笔固化。
54		if e.Cash() != 973 || e.ReservedCash() != 114 || e.AvailableCash() != 859 {
55			t.Fatalf("前置资金错误: cash=%d reserved=%d available=%d",
56				e.Cash(), e.ReservedCash(), e.AvailableCash())
57		}
58		if e.Position("A") != 3 || e.Sellable("A") != 1 || e.Position("B") != 0 {
59			t.Fatalf("前置持仓错误: A.pos=%d A.sellable=%d B.pos=%d",
60				e.Position("A"), e.Sellable("A"), e.Position("B"))
