117		oSell, _ := e.Order(sellA)
118		if oSell.Status != StatusPending || oSell.Side != Sell || oSell.Qty != 2 ||
119			oSell.Limit != 8 || oSell.Remaining() != 2 || oSell.Reason != "" {
120			t.Fatalf("A 卖单数量与可卖占用不得改变: %+v", oSell)
121		}
122	
123		// 第一次下调恰好新增一条撤销记录：说明限额下调原因，携带当时 A 报价
124		// （序号1、时刻10、价格10）与新限额 10 快照，已成交 0、被取消剩余 2。
125		newRecs10 := e.Records()[recsBefore10:]
126		if len(newRecs10) != 1 {
127			t.Fatalf("下调到 10 应只新增 1 条撤销记录，实际 %d 条: %+v", len(newRecs10), newRecs10)
128		}
129		cr2 := newRecs10[0]
130		if cr2.Kind != RecordCanceled || cr2.OrderID != bidA2 || cr2.Symbol != "A" || cr2.Side != Buy {
131			t.Fatalf("应为订单2 的撤销记录: %+v", cr2)
132		}
133		if cr2.Qty != 2 || cr2.Filled != 0 || cr2.Remaining != 2 {
134			t.Fatalf("订单2 撤销记录应区分已成交 0 与被取消剩余 2: %+v", cr2)
135		}
136		if !cr2.QuoteValid || cr2.QuoteSeq != 1 || cr2.QuoteMoment != 10 || cr2.QuotePrice != 10 {
137			t.Fatalf("订单2 撤销记录应携带当时 A 报价（序号1、时刻10、价格10）: %+v", cr2)
138		}
139		if !cr2.MaxPositionValid || cr2.MaxPosition != 10 {
140			t.Fatalf("订单2 撤销记录应携带新限额 10 快照: %+v", cr2)
141		}
142		if !strings.Contains(cr2.Reason, "10") {
143			t.Fatalf("订单2 撤销原因应说明限额下调至 10: %q", cr2.Reason)
144		}
145	
146		// ---- 第二次下调：A 限额 10 -> 2 ----
147		recsBefore2 := len(e.Records())
148		canceled2, err := e.SetMaxPosition("A", 2)
149		if err != nil {
150			t.Fatalf("下调 A 限额到 2 不应报错: %v", err)
151		}
152		// 持仓 3 本身已超过新限额 2（待成交卖单不抵减持仓）：撤销订单1 的全部
153		// 剩余 7 份，保留已成交 3 份，不自动卖出持仓。
154		if len(canceled2) != 1 || canceled2[0] != bidA1 {
155			t.Fatalf("下调到 2 应只撤销订单 %d，实际 %v", bidA1, canceled2)
156		}
157		if max, ok := e.MaxPosition("A"); !ok || max != 2 {
158			t.Fatalf("A 限额应已更新为 2: max=%d ok=%v", max, ok)
159		}
160	
161		// 资金：再释放 7×10=70，占用现金只剩 B 买单的 20；余额仍为 973，可用 953。
162		if e.Cash() != 973 || e.ReservedCash() != 20 || e.AvailableCash() != 953 {
163			t.Fatalf("下调到 2 后资金错误: cash=%d reserved=%d available=%d",
164				e.Cash(), e.ReservedCash(), e.AvailableCash())
165		}
166		// 持仓不自动卖出：A 持仓仍为 3、可卖仍为 1，原有卖单继续有效。
167		if e.Position("A") != 3 || e.Sellable("A") != 1 || e.Position("B") != 0 {
168			t.Fatalf("下调到 2 后持仓错误: A.pos=%d A.sellable=%d B.pos=%d",
169				e.Position("A"), e.Sellable("A"), e.Position("B"))
170		}
171		o1, _ = e.Order(bidA1)
172		if o1.Status != StatusCanceled || o1.Qty != 10 || o1.Filled != 3 || o1.Remaining() != 0 {
173			t.Fatalf("订单1 应保留已成交 3 并撤销剩余 7: %+v", o1)
174		}
175		if !strings.Contains(o1.Reason, "持仓 3") || !strings.Contains(o1.Reason, "2") {
176			t.Fatalf("订单1 撤销原因应说明持仓 3 已超过新限额 2: %q", o1.Reason)
177		}
178		oB, _ = e.Order(bidB)
179		if oB.Status != StatusPending || oB.Remaining() != 4 {
180			t.Fatalf("B 买单在第二次下调后仍应保持有效: %+v", oB)
181		}
182		oSell, _ = e.Order(sellA)
183		if oSell.Status != StatusPending || oSell.Remaining() != 2 || oSell.Reason != "" {
184			t.Fatalf("A 卖单在第二次下调后仍应继续有效: %+v", oSell)
185		}
186	
187		// 第二次下调恰好新增一条撤销记录：说明持仓超限原因，携带当时 A 报价
188		// 与新限额 2 快照，区分已成交 3 与被取消剩余 7。
189		newRecs2 := e.Records()[recsBefore2:]
190		if len(newRecs2) != 1 {
191			t.Fatalf("下调到 2 应只新增 1 条撤销记录，实际 %d 条: %+v", len(newRecs2), newRecs2)
192		}
193		cr1 := newRecs2[0]
194		if cr1.Kind != RecordCanceled || cr1.OrderID != bidA1 || cr1.Symbol != "A" || cr1.Side != Buy {
195			t.Fatalf("应为订单1 的撤销记录: %+v", cr1)
196		}
197		if cr1.Qty != 10 || cr1.Filled != 3 || cr1.Remaining != 7 {
198			t.Fatalf("订单1 撤销记录应区分已成交 3 与被取消剩余 7: %+v", cr1)
199		}
200		if !cr1.QuoteValid || cr1.QuoteSeq != 1 || cr1.QuoteMoment != 10 || cr1.QuotePrice != 10 {
201			t.Fatalf("订单1 撤销记录应携带当时 A 报价（序号1、时刻10、价格10）: %+v", cr1)
202		}
203		if !cr1.MaxPositionValid || cr1.MaxPosition != 2 {
204			t.Fatalf("订单1 撤销记录应携带新限额 2 快照: %+v", cr1)
205		}
206		if !strings.Contains(cr1.Reason, "持仓 3") || !strings.Contains(cr1.Reason, "2") {
207			t.Fatalf("订单1 撤销原因应说明持仓 3 已超过新限额 2: %q", cr1.Reason)
208		}
209	
210		// 两次撤销记录按实际撤销顺序保存：先订单2（限额 10），后订单1（限额 2）。
211		var cancelOrder []int64
212		for _, r := range e.Records() {
213			if r.Kind == RecordCanceled {
214				cancelOrder = append(cancelOrder, r.OrderID)
215			}
216		}
217		if !reflect.DeepEqual(cancelOrder, []int64{bidA2, bidA1}) {
218			t.Fatalf("撤销记录应按实际撤销顺序保存为 [%d %d]，实际 %v", bidA2, bidA1, cancelOrder)
219		}
220	
221		// 第二次下调不能改写第一次的撤销记录。
222		if got := e.Records()[recsBefore10]; !reflect.DeepEqual(got, cr2) {
223			t.Fatalf("第二次下调不得改写第一次的撤销记录:\n第一次: %+v\n现在:   %+v", cr2, got)
224		}
225	
226		// 既有成交记录保持原值：成交 3 份、价格 9，快照仍为当时的限额 20。
227		var fillRec *Record
228		recs := e.Records()
229		for i := range recs {
230			if recs[i].Kind == RecordFilled && recs[i].TradeID == 1 {
231				fillRec = &recs[i]
232			}
233		}
234		if fillRec == nil {
235			t.Fatal("应存在订单1 的成交记录")
236		}
237		if fillRec.OrderID != bidA1 || fillRec.Qty != 3 || fillRec.TradePrice != 9 ||
238			fillRec.Filled != 3 || fillRec.Remaining != 7 {
239			t.Fatalf("成交记录应保持成交 3 份、价格 9、当时剩余 7: %+v", *fillRec)
240		}
241		if !fillRec.MaxPositionValid || fillRec.MaxPosition != 20 {
242			t.Fatalf("成交记录的限额快照应保持成交时的 20，不被后续下调改写: %+v", *fillRec)
243		}
244	
245		// 全部记录中不得出现 B 买单或 A 卖单的撤销。
246		for _, r := range e.Records() {
247			if r.Kind == RecordCanceled && (r.OrderID == bidB || r.OrderID == sellA) {
248				t.Fatalf("B 买单与 A 卖单不得被 A 限额下调撤销: %+v", r)
249			}
250		}
251	}
252	
253	// TestSetMaxPositionLowerToCurrentUsageCancelsNothing 钉住边界：
254	// 下调后的新限额恰好等于当前“持仓 + 有效买单剩余量”时不撤任何单。
255	func TestSetMaxPositionLowerToCurrentUsageCancelsNothing(t *testing.T) {
256		e, bidA1, bidA2, bidB, sellA := lowerMaxSetup(t)
257	
258		// 持仓 3 + A 买单剩余 9 = 12，下调到 12 恰好用满额度。
259		recsBefore := len(e.Records())
260		canceled, err := e.SetMaxPosition("A", 12)
261		if err != nil {
262			t.Fatalf("下调 A 限额到 12 不应报错: %v", err)
263		}
264		if len(canceled) != 0 {
265			t.Fatalf("新限额恰好等于当前占用时不应撤单，实际 %v", canceled)
266		}
267		if max, ok := e.MaxPosition("A"); !ok || max != 12 {
268			t.Fatalf("A 限额应已更新为 12: max=%d ok=%v", max, ok)
269		}
270		if e.Cash() != 973 || e.ReservedCash() != 114 || e.AvailableCash() != 859 {
271			t.Fatalf("未撤单时资金占用必须保持原值: cash=%d reserved=%d available=%d",
272				e.Cash(), e.ReservedCash(), e.AvailableCash())
273		}
274		if e.Position("A") != 3 || e.Sellable("A") != 1 {
275			t.Fatalf("未撤单时持仓与可卖必须保持原值: pos=%d sellable=%d",
276				e.Position("A"), e.Sellable("A"))
277		}
278		for _, id := range []int64{bidA1, bidA2, bidB, sellA} {
279			o, _ := e.Order(id)
280			if o.Status == StatusCanceled {
281				t.Fatalf("订单 %d 不应被撤销: %+v", id, o)
282			}
283		}
284		if o, _ := e.Order(bidA1); o.Status != StatusPartial || o.Remaining() != 7 {
285			t.Fatalf("订单1 应保持部分成交、剩余 7: %+v", o)
286		}
287		if len(e.Records()) != recsBefore {
288			t.Fatal("恰好用满额度的下调不得追加任何记录")
289		}
290	}
