		// 零上限立即触线：当前亏损记 0，0 >= 0；保留基准计算所用的各持仓报价。
		e.triggerRiskLocked(RiskTriggerStartDay, 0, 0, RiskValuation{Equity: val.Equity, Loss: 0}, refs)
	}
